"""Supplier receipts, the goods received notes (ERD s3.5). Never edited after confirmation."""

from django.conf import settings
from django.db import models
from django.db.models import CharField, Q, Value
from django.db.models.functions import Cast, Concat, LPad


class GoodsReceipt(models.Model):
    # 'GRN-' || lpad(id::text, 6, '0'), generated by the database (E2).
    reference = models.GeneratedField(
        expression=Concat(Value("GRN-"), LPad(Cast("id", CharField()), 6, Value("0"))),
        output_field=CharField(max_length=20),
        db_persist=True,
        unique=True,
    )
    location = models.ForeignKey(
        "branches.Branch", on_delete=models.PROTECT, related_name="goods_receipts"
    )
    supplier_name = models.CharField(max_length=150)
    received_by = models.ForeignKey(
        settings.AUTH_USER_MODEL, on_delete=models.PROTECT, related_name="+"
    )
    received_at = models.DateTimeField()
    notes = models.TextField(blank=True, default="")
    operation = models.OneToOneField(
        "stock_ledger.Operation", on_delete=models.PROTECT, related_name="goods_receipt"
    )


class GoodsReceiptLine(models.Model):
    receipt = models.ForeignKey(GoodsReceipt, on_delete=models.PROTECT, related_name="lines")
    line_no = models.PositiveSmallIntegerField()
    item = models.ForeignKey("inventory.Item", on_delete=models.PROTECT, related_name="+")
    quantity = models.DecimalField(max_digits=12, decimal_places=3)
    # Mandatory on every receipt line (E18). Read by Super Admin and Warehouse Admin only.
    unit_cost = models.DecimalField(max_digits=12, decimal_places=2)

    class Meta:
        constraints = [
            models.UniqueConstraint(fields=["receipt", "line_no"], name="warehouse_line_no_uniq"),
            models.CheckConstraint(condition=Q(quantity__gt=0), name="warehouse_line_quantity_ck"),
            models.CheckConstraint(condition=Q(unit_cost__gte=0), name="warehouse_line_cost_ck"),
        ]
        indexes = [models.Index(fields=["item"], name="warehouse_line_item_idx")]
